import torch as t
_dd_out_views = []
def _dd_wrap(_name):
    _orig = getattr(getattr(t, _name), '_dd_original', getattr(t, _name))
    def _w(*a, **k):
        o = k.get('out')
        if o is not None:
            _dd_out_views.append((_name, tuple(o.shape), tuple(o.stride()), o.untyped_storage().nbytes() // o.element_size()))
        return _orig(*a, **k)
    _w._dd_original = _orig
    setattr(t, _name, _w)
for _dd_n in ('arange', 'linspace'):
    _dd_wrap(_dd_n)

