answer_code:
import torch as t


def solve(n, k, lo, hi, col):
    """One column split between a count and a ramp."""
    canvas = t.zeros((n, 2))
    t.arange(k, out=canvas[:k, col])
    if n - k > 0:
        t.linspace(lo, hi, n - k, out=canvas[k:, col])
    return canvas.tolist()


example = (5, 2, 0.0, 1.0, 1)
print(solve(*example))

