import torch as t

def solve(n1,o1,s1,n2,o2,s2,i):
    def group(n,a,b,s):
        seq=t.nn.Sequential()
        seq.add_module("0",ResidualBlock(a,b,s))
        k=1
        for extra in [b]*(n-1):
            seq.add_module(str(k),ResidualBlock(b,b,1))
            k+=1
        return seq
    class TwoGroups(t.nn.Module):
        def __init__(self):
            super().__init__()
            self.g1=group(n1,i,o1,s1)
            self.g2=group(n2,o1,o2,s2)
        def forward(self,x):
            return self.g2(self.g1(x))
    return TwoGroups()

