import torch as t

def solve(n,i,o,s):
    class Group(t.nn.Module):
        def __init__(self):
            super().__init__()
            self.blocks=t.nn.Sequential()
            self.blocks.add_module("0",ResidualBlock(i,o,s))
            k=1
            for extra in [o]*(n-1):
                self.blocks.add_module(str(k),ResidualBlock(o,o,1))
                k+=1
        def forward(self,x):
            outs=[]
            for block in self.blocks:
                x=block(x)
                outs.append(x)
            return outs
    return Group()

