import torch as t

def solve(cin,c0,n_blocks,out_feats,strides,n_classes):
    class ResNet(t.nn.Module):
        def __init__(self):
            super().__init__()
            self.in_layers=t.nn.Sequential(t.nn.Conv2d(cin,c0,kernel_size=7,stride=2,padding=3),t.nn.BatchNorm2d(c0),t.nn.ReLU(),t.nn.MaxPool2d(kernel_size=3,stride=2,padding=1))
            self.residual_layers=t.nn.Sequential()
            i=c0
            k=0
            for n in n_blocks:
                self.residual_layers.add_module(str(k),BlockGroup(n,i,out_feats[k],strides[k]))
                i=out_feats[k]
                k+=1
            self.head=t.nn.Linear(out_feats[-1],n_classes)
        def forward(self,x):
            f=self.residual_layers(self.in_layers(x)).mean((2,3))
            return (f,self.head(f))
    return ResNet()

