import torch as t

def solve(m,x):
    flagged=[]
    handles=[]
    def check(module,inputs,output):
        if t.isnan(output).any():
            flagged.append((module,t.isnan(inputs[0]).any().item()))
    def add_hook(module):
        handles.append(module.register_forward_hook(check))
    m.apply(add_hook)
    m(x)
    for h in handles:
        h.remove()
    m(x)
    first=False
    for module,had_nan_in in flagged[:1]:
        first=had_nan_in==False
    return (len(flagged),first)

