    def Rear(self) -> int:
        if self.isEmpty():
            return -1
        return self.values[(self.front + self.size - 1) % self.capacity]

    def isEmpty(self) -> bool:
        return self.size == 0

    def isFull(self) -> bool:
        return self.size == self.capacity

