from collections import defaultdict, OrderedDict

class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.values = {}
        self.frequencies = {}
        self.groups = defaultdict(OrderedDict)
        self.minimum_frequency = 0

    def _touch(self, key: int) -> None:
        frequency = self.frequencies[key]
        del self.groups[frequency][key]
        if frequency == self.minimum_frequency and not self.groups[frequency]:
            self.minimum_frequency += 1
        self.frequencies[key] = frequency + 1
        self.groups[frequency + 1][key] = None

    def get(self, key: int) -> int:
        if key not in self.values:
            return -1
        self._touch(key)
        return self.values[key]

    def put(self, key: int, value: int) -> None:
        if self.capacity == 0:
            return
        if key in self.values:
            self.values[key] = value
            self._touch(key)
            return
        if len(self.values) == self.capacity:
            evicted, _ = self.groups[self.minimum_frequency].popitem(last=False)
            del self.values[evicted]
            del self.frequencies[evicted]
        self.values[key] = value
        self.frequencies[key] = 1
        self.groups[1][key] = None
        self.minimum_frequency = 1

