class ArrayStack:
    def __init__(self, capacity):
        self.capacity = capacity
        self.data = [None] * capacity
        self.top_index = -1

    def push(self, x):
        if self.top_index + 1 < self.capacity:
            self.top_index += 1
            self.data[self.top_index] = x

    def pop(self):
        if self.top_index >= 0:
            self.data[self.top_index] = None
            self.top_index -= 1

    def peek(self):
        if self.top_index < 0:
            return -1
        return self.data[self.top_index]

    def isEmpty(self):
        return self.top_index == -1

    def isFull(self):
        return self.top_index + 1 == self.capacity

