def quickSort(arr, low, high):
    stack = [(low, high)]
    while stack:
        left, right = stack.pop()
        if left >= right:
            continue
        i, j = left, right
        pivot = arr[(left + right) // 2]
        while i <= j:
            while arr[i] < pivot:
                i += 1
            while arr[j] > pivot:
                j -= 1
            if i <= j:
                arr[i], arr[j] = arr[j], arr[i]
                i += 1
                j -= 1
        if left < j:
            stack.append((left, j))
        if i < right:
            stack.append((i, right))
    return arr

