def inversionCount(arr):
    values = arr[:]

    def sort_count(left, right):
        if right - left <= 1:
            return 0
        mid = (left + right) // 2
        count = sort_count(left, mid) + sort_count(mid, right)
        merged = []
        i, j = left, mid
        while i < mid and j < right:
            if values[i] <= values[j]:
                merged.append(values[i])
                i += 1
            else:
                merged.append(values[j])
                count += mid - i
                j += 1
        merged.extend(values[i:mid])
        merged.extend(values[j:right])
        values[left:right] = merged
        return count

    return sort_count(0, len(values))

