def numProvinces(adj, V):
    seen = [False] * V
    provinces = 0

    for start in range(V):
        if seen[start]:
            continue
        provinces += 1
        seen[start] = True
        stack = [start]

        while stack:
            node = stack.pop()
            for neighbor in range(V):
                if adj[node][neighbor] and not seen[neighbor]:
                    seen[neighbor] = True
                    stack.append(neighbor)

    return provinces

